"""Dérivés et volatilité implicite : options, grecques, Black-Scholes, surface de volatilité, stratégies d'options."""
from __future__ import annotations

from patrick.knowledge.dictionary import d

T = "derives"
TERMS = [
    d(T, "option", "Option", "Option", 2,
      "Contrat qui donne le droit, mais pas l'obligation, d'acheter (call) ou de vendre (put) un actif à un prix fixé (strike) jusqu'à une date (échéance). L'acheteur paie une prime et risque au plus cette prime ; le vendeur encaisse la prime et s'expose à une perte potentiellement grande.",
      "Contract giving the right, but not the obligation, to buy (call) or sell (put) an asset at a set price (strike) until a date (expiry). The buyer pays a premium and risks at most that premium; the seller collects the premium and faces a potentially large loss.",
      see="call_put strike_prime_echeance black_scholes"),
    d(T, "call_put", "Call et put", "Call and put", 2,
      "Un call profite d'une hausse du sous-jacent (droit d'acheter), un put d'une baisse (droit de vendre). À l'échéance, un call vaut max(S − K ; 0) et un put max(K − S ; 0), où S est le cours et K le strike.",
      "A call profits from a rise in the underlying (right to buy), a put from a fall (right to sell). At expiry a call is worth max(S − K, 0) and a put max(K − S, 0), where S is the price and K the strike.",
      formula=r"C_T = \max(S_T - K,\,0), \qquad P_T = \max(K - S_T,\,0)", see="option moneyness"),
    d(T, "strike_prime_echeance", "Strike, prime et échéance", "Strike, premium and expiry", 2,
      "Le strike (prix d'exercice) est le prix auquel on peut acheter ou vendre ; la prime est le prix de l'option ; l'échéance est la date limite. À sous-jacent identique, une prime est plus élevée si l'échéance est lointaine et la volatilité forte.",
      "The strike is the price at which one may buy or sell; the premium is the option's price; expiry is the deadline. For the same underlying, a premium is higher with a distant expiry and high volatility.",
      see="option valeur_intrinseque_temps"),
    d(T, "valeur_intrinseque_temps", "Valeur intrinsèque et valeur temps", "Intrinsic and time value", 2,
      "La prime d'une option se décompose en valeur intrinsèque (ce qu'elle rapporterait si elle était exercée maintenant) et valeur temps (le pari que le cours bouge encore). La valeur temps s'érode jusqu'à zéro à l'échéance.",
      "An option's premium splits into intrinsic value (what it would pay if exercised now) and time value (the bet that the price will still move). Time value erodes to zero at expiry.",
      see="theta strike_prime_echeance"),
    d(T, "moneyness", "Position par rapport au strike (ITM, ATM, OTM)", "Moneyness (ITM, ATM, OTM)", 2,
      "Une option est dans la monnaie (ITM) si l'exercer rapporterait de l'argent, à la monnaie (ATM) si le strike est proche du cours, hors de la monnaie (OTM) sinon. Les options OTM sont peu chères et ont peu de chances d'être exercées.",
      "An option is in the money (ITM) if exercising it would pay, at the money (ATM) if the strike is near the price, out of the money (OTM) otherwise. OTM options are cheap and unlikely to be exercised.",
      see="call_put delta", alias="ITM; ATM; OTM"),
    d(T, "option_europeenne_americaine", "Option européenne et américaine", "European and American option", 3,
      "Une option européenne ne s'exerce qu'à l'échéance ; une américaine peut l'être à tout moment. L'exercice anticipé a un intérêt surtout pour les puts et pour les calls sur actions versant un dividende.",
      "A European option can only be exercised at expiry; an American one at any time. Early exercise matters mostly for puts and for calls on dividend-paying stocks.",
      see="option"),
    d(T, "parite_call_put", "Parité call-put", "Put-call parity", 3,
      "Relation d'arbitrage entre le prix d'un call et d'un put européens de même strike et échéance : C − P = S − K e^{−rT}. Si elle est violée, un arbitrage sans risque existe ; elle relie la volatilité des calls et des puts.",
      "Arbitrage relation between the price of a European call and put with the same strike and expiry: C − P = S − K e^{−rT}. If violated, a riskless arbitrage exists; it links call and put volatilities.",
      formula=r"C - P = S - K e^{-rT}", see="call_put black_scholes"),
    d(T, "black_scholes", "Modèle de Black-Scholes", "Black–Scholes model", 3,
      "Formule (1973) du prix d'une option européenne sous l'hypothèse d'un cours qui suit un mouvement brownien géométrique à volatilité constante. Elle n'est pas fidèle à la réalité (queues épaisses, volatilité variable) mais sert de langage commun : on cote les options en volatilité implicite.",
      "1973 formula for a European option's price assuming the price follows a geometric Brownian motion with constant volatility. It is not faithful to reality (fat tails, varying volatility) but serves as a common language: options are quoted in implied volatility.",
      formula=r"C = S\,\Phi(d_1) - K e^{-rT}\Phi(d_2), \quad d_{1,2} = \frac{\ln(S/K) + (r \pm \sigma^2/2)T}{\sigma\sqrt{T}}", see="vol_implicite grecques mouvement_brownien"),
    d(T, "vol_implicite", "Volatilité implicite", "Implied volatility", 3,
      "Volatilité qu'il faut mettre dans la formule de Black-Scholes pour retrouver le prix observé d'une option : c'est l'avis du marché sur la volatilité future. Elle se compare à la volatilité réalisée passée pour juger si les options sont chères.",
      "Volatility to plug into the Black–Scholes formula to match an option's observed price: the market's view of future volatility. It is compared with past realised volatility to judge whether options are expensive.",
      see="black_scholes vol_realisee_vs_implicite vix_indice", alias="vol implicite; IV"),
    d(T, "grecques", "Les grecques (delta, gamma, vega, theta, rho)", "The Greeks (delta, gamma, vega, theta, rho)", 3,
      "Sensibilités du prix d'une option aux paramètres du marché : delta (au cours), gamma (variation du delta), vega (à la volatilité), theta (au temps), rho (aux taux). Elles servent à mesurer et à couvrir le risque d'un portefeuille d'options.",
      "Sensitivities of an option's price to market parameters: delta (to price), gamma (change in delta), vega (to volatility), theta (to time), rho (to rates). They measure and hedge an option portfolio's risk.",
      see="delta gamma_option vega theta rho_option"),
    d(T, "delta", "Delta", "Delta", 3,
      "Variation du prix d'une option pour 1 euro de variation du sous-jacent : entre 0 et 1 pour un call, entre −1 et 0 pour un put. Vers 0,5 à la monnaie. Il est aussi la quantité de sous-jacent qui couvre l'option.",
      "Change in an option's price for 1 euro of change in the underlying: between 0 and 1 for a call, −1 and 0 for a put. About 0.5 at the money. It is also the quantity of underlying that hedges the option.",
      formula=r"\Delta = \frac{\partial V}{\partial S}", see="grecques couverture_delta"),
    d(T, "gamma_option", "Gamma", "Gamma", 3,
      "Variation du delta quand le cours bouge : la courbure du prix de l'option. Fort à la monnaie et près de l'échéance ; un gamma positif profite des grands mouvements, un gamma négatif en souffre.",
      "Change in delta as the price moves: the curvature of the option price. Large at the money and near expiry; positive gamma profits from big moves, negative gamma suffers from them.",
      formula=r"\Gamma = \frac{\partial^2 V}{\partial S^2}", see="grecques gamma_scalping"),
    d(T, "vega", "Vega", "Vega", 3,
      "Variation du prix d'une option pour 1 point de volatilité implicite. Toujours positif pour l'acheteur d'option : acheter une option, c'est être long de volatilité.",
      "Change in an option's price for 1 point of implied volatility. Always positive for an option buyer: buying an option is being long volatility.",
      formula=r"\mathcal{V} = \frac{\partial V}{\partial \sigma}", see="grecques vol_implicite"),
    d(T, "theta", "Theta", "Theta", 3,
      "Perte de valeur d'une option par jour qui passe, à cours et volatilité inchangés. L'acheteur le paie, le vendeur l'encaisse : c'est le prix du droit de détenir l'option.",
      "Loss of an option's value per passing day, with price and volatility unchanged. The buyer pays it, the seller collects it: it is the price of holding the right.",
      formula=r"\Theta = \frac{\partial V}{\partial t}", see="grecques valeur_intrinseque_temps"),
    d(T, "rho_option", "Rho", "Rho", 3,
      "Variation du prix d'une option pour 1 point de variation du taux d'intérêt. Faible pour les options courtes, plus sensible pour les options de longue durée.",
      "Change in an option's price for 1 point of change in the interest rate. Small for short options, more sensitive for long-dated ones.",
      see="grecques"),
    d(T, "skew_vol", "Smile et skew de volatilité", "Volatility smile and skew", 3,
      "La volatilité implicite varie selon le strike : sur les indices actions, les puts hors de la monnaie ont une volatilité plus forte que les calls (skew) car les investisseurs paient cher la protection contre un krach. Black-Scholes ne le prévoit pas.",
      "Implied volatility varies with strike: on equity indices, out-of-the-money puts carry higher volatility than calls (skew) because investors pay up for crash protection. Black–Scholes does not predict this.",
      see="vol_implicite surface_de_vol", alias="smile; skew"),
    d(T, "surface_de_vol", "Surface de volatilité et structure par terme", "Volatility surface and term structure", 3,
      "Ensemble des volatilités implicites selon le strike et l'échéance. Sa coupe par échéance est la structure par terme : en général croissante en temps calme (contango de volatilité), inversée en crise.",
      "The set of implied volatilities by strike and expiry. Its cut by expiry is the term structure: usually upward sloping in calm times (volatility contango), inverted in a crisis.",
      see="skew_vol vix_indice"),
    d(T, "vol_realisee_vs_implicite", "Volatilité réalisée et volatilité implicite", "Realised vs implied volatility", 3,
      "La volatilité réalisée est mesurée sur le passé ; l'implicite est la prévision du marché. En moyenne l'implicite dépasse la réalisée : c'est la prime de risque de variance, que les vendeurs d'options encaissent et paient parfois très cher en crise.",
      "Realised volatility is measured on the past; implied is the market's forecast. On average implied exceeds realised: the variance risk premium, which option sellers collect and sometimes pay dearly for in a crisis.",
      see="vol_implicite vrp_proxy variance_swap"),
    d(T, "variance_swap", "Swap de variance", "Variance swap", 3,
      "Contrat échangeant la variance réalisée d'un indice contre un niveau fixé à l'avance : pure exposition à la volatilité, sans passer par la couverture delta. Son niveau d'équilibre se déduit d'un panier d'options sur toute la gamme de strikes.",
      "Contract exchanging an index's realised variance for a level fixed in advance: pure volatility exposure with no delta hedging. Its fair level is derived from a basket of options across all strikes.",
      see="vol_realisee_vs_implicite vix_indice"),
    d(T, "couverture_delta", "Couverture en delta", "Delta hedging", 3,
      "Neutraliser l'exposition d'une option au cours en détenant ou vendant delta unités du sous-jacent, rééquilibrées au fil du temps. Le résultat dépend alors surtout de l'écart entre volatilité réalisée et implicite.",
      "Neutralising an option's exposure to price by holding or selling delta units of the underlying, rebalanced over time. The result then depends mostly on the gap between realised and implied volatility.",
      see="delta gamma_scalping"),
    d(T, "gamma_scalping", "Gamma scalping", "Gamma scalping", 3,
      "Stratégie qui détient des options (gamma positif), se couvre en delta et rééquilibre souvent : elle gagne sur les oscillations du cours, tant que la volatilité réalisée dépasse celle payée dans la prime.",
      "Strategy holding options (positive gamma), delta-hedging and rebalancing often: it earns from price oscillations as long as realised volatility exceeds what was paid in the premium.",
      see="gamma_option couverture_delta"),
    d(T, "straddle_strangle", "Straddle et strangle", "Straddle and strangle", 3,
      "Un straddle achète un call et un put de même strike : il gagne si le cours bouge fortement dans un sens ou l'autre. Un strangle utilise deux strikes différents, moins cher mais demandant un plus grand mouvement. On les utilise pour parier sur un événement.",
      "A straddle buys a call and a put with the same strike: it wins if the price moves strongly either way. A strangle uses two different strikes, cheaper but needing a bigger move. They are used to bet on an event.",
      see="mouvement_implicite_annonce option"),
    d(T, "spread_options", "Écart d'options (spread vertical)", "Option spread", 3,
      "Achat d'une option et vente d'une autre de strike différent : on plafonne gain et perte pour réduire le coût. Un « bull call spread » parie sur une hausse modérée à moindre prime qu'un call seul.",
      "Buying one option and selling another with a different strike: gain and loss are capped to lower the cost. A bull call spread bets on a moderate rise at a lower premium than a lone call.",
      see="option"),
    d(T, "covered_call_protective_put", "Call couvert et put de protection", "Covered call and protective put", 3,
      "Un call couvert vend un call sur des actions déjà détenues : on encaisse une prime en échange de plafonner la hausse. Un put de protection achète un put contre les actions détenues : une assurance contre la baisse, à la prime près.",
      "A covered call sells a call on shares already held: one collects a premium in exchange for capping the upside. A protective put buys a put against held shares: insurance against a fall, at the cost of the premium.",
      see="option collar"),
    d(T, "collar", "Collar (tunnel)", "Collar", 3,
      "Combinaison d'un put acheté (protection) et d'un call vendu (financement) sur une action détenue : le résultat reste dans un tunnel entre une perte maximale et un gain maximal, souvent à coût nul.",
      "Combination of a bought put (protection) and a sold call (financing) on a held stock: the outcome stays in a tunnel between a maximum loss and a maximum gain, often at zero cost.",
      see="covered_call_protective_put"),
    d(T, "open_interest_put_call", "Open interest et ratio put/call", "Open interest and put/call ratio", 2,
      "L'open interest est le nombre de contrats ouverts à un instant ; le ratio put/call rapporte le volume (ou l'open interest) des puts à celui des calls. Un ratio élevé traduit une demande de protection, parfois lu comme signal contrarien.",
      "Open interest is the number of contracts outstanding at a moment; the put/call ratio compares the volume (or open interest) of puts to calls. A high ratio reflects demand for protection, sometimes read as a contrarian signal.",
      see="vol_implicite", alias="put-call ratio"),
    d(T, "cout_de_portage", "Coût de portage (cost of carry)", "Cost of carry", 3,
      "Coût de détention d'un actif jusqu'à une date : financement, stockage, assurance, moins les revenus (dividendes, intérêts). Il fixe l'écart entre le prix à terme et le comptant : F = S e^{(r + c − y)T}.",
      "Cost of holding an asset until a date: financing, storage, insurance, minus income (dividends, interest). It sets the gap between forward and spot: F = S e^{(r + c − y)T}.",
      formula=r"F = S\,e^{(r + c - y)T}", see="contango_backwardation forward"),
    d(T, "risque_de_base", "Risque de base", "Basis risk", 3,
      "Risque que l'instrument de couverture ne suive pas exactement l'actif couvert : le prix du future et celui du comptant ne convergent pas parfaitement. La couverture réduit le risque sans jamais l'annuler.",
      "Risk that the hedging instrument does not follow the hedged asset exactly: the futures price and the spot price do not converge perfectly. Hedging reduces risk without ever removing it.",
      see="future forward"),
    d(T, "mouvement_brownien", "Mouvement brownien géométrique", "Geometric Brownian motion", 3,
      "Modèle de cours où les log-rendements sont gaussiens, indépendants, de moyenne et de variance proportionnelles au temps : dS = μ S dt + σ S dW. C'est le socle de Black-Scholes ; il ignore les queues épaisses et la volatilité qui varie.",
      "Price model where log returns are Gaussian, independent, with mean and variance proportional to time: dS = μ S dt + σ S dW. It underlies Black–Scholes; it ignores fat tails and varying volatility.",
      formula=r"dS_t = \mu S_t\,dt + \sigma S_t\,dW_t", see="black_scholes loi_normale"),
    d(T, "mouvement_implicite_annonce", "Mouvement implicite d'une annonce", "Implied move of an announcement", 3,
      "Amplitude de variation du cours que les options prévoient autour d'un événement (résultats), lue sur le prix d'un straddle sur l'échéance qui le suit : prime du straddle / cours. On la compare à ce qui se produit ensuite pour juger si le marché a sur- ou sous-estimé.",
      "Size of the price move options expect around an event (earnings), read from the price of a straddle on the expiry just after it: straddle premium / price. It is compared with what actually happens to judge whether the market over- or underestimated.",
      see="straddle_strangle earnings_volatilite"),
    d(T, "appel_marge_future", "Marge de variation (futures)", "Variation margin (futures)", 2,
      "Chaque jour, les gains et pertes d'un future sont réglés en espèces entre les comptes (marque au marché). Une perte exige un versement immédiat : un fort levier peut forcer à vendre au mauvais moment.",
      "Each day a future's gains and losses are settled in cash between accounts (mark to market). A loss demands an immediate payment: heavy leverage can force selling at the wrong time.",
      see="future marge appel_de_marge"),
]
